import React, { useState, useEffect } from 'react';
import './Aiiot.css';

const Aiiot_innovation = () => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [heroImages, setHeroImages] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Initialize Feather Icons (if using feather-icons library)
    if (window.feather) {
      window.feather.replace();
    }

    // Reveal on scroll animation
    const scrollElements = document.querySelectorAll(".reveal-on-scroll");

    const elementInView = (el, dividend = 1) => {
      const elementTop = el.getBoundingClientRect().top;
      return elementTop <= (window.innerHeight || document.documentElement.clientHeight) / dividend;
    };

    const displayScrollElement = (element) => element.classList.add("is-visible");

    const handleScrollAnimation = () => {
      scrollElements.forEach((el) => {
        if (elementInView(el, 1.25)) displayScrollElement(el);
      });
    };

    handleScrollAnimation(); // Initial check
    window.addEventListener("scroll", handleScrollAnimation);

    // Setup carousel
    setupCarousel();

    return () => {
      window.removeEventListener("scroll", handleScrollAnimation);
    };
  }, []);

  const setupCarousel = async () => {
    try {
      const response = await fetch('https://picsum.photos/v2/list?page=1&limit=5');
      const data = await response.json();
      const images = data.map(img => img.download_url);
      setHeroImages(images);
      setIsLoading(false);
    } catch (error) {
      console.error('Error loading images:', error);
      const fallbackImages = [
        'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&h=600&fit=crop',
        'https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&h=600&fit=crop',
        'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=800&h=600&fit=crop'
      ];
      setHeroImages(fallbackImages);
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (heroImages.length === 0) return;

    const interval = setInterval(() => {
      setCurrentImageIndex((prevIndex) => (prevIndex + 1) % heroImages.length);
    }, 4000);

    return () => clearInterval(interval);
  }, [heroImages]);

  const handleIndicatorClick = (index) => {
    setCurrentImageIndex(index);
  };

  const teamMembers = [
    {
      name: "Dr. Ajay Kumar",
      role: "Principal Investigator",
      description: "Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.",
      icon: "user"
    },
    {
      name: "Mr. Albins Paul",
      role: "Co-Investigator",
      description: "Assistant Professor at ASIET's ECE Department, specializing in Microwave & Television Engineering.",
      icon: "user"
    },
    {
      name: "Prof. P.V. Rajaraman",
      role: "Co-Investigator",
      description: "Assistant Professor, CTO, and Head of the AI Department at ASIET. He specializes in NLP and XAI, has multiple publications, and is currently pursuing his Ph.D.",
      icon: "user"
    },
    {
      name: "Mr. Abhijith Pm",
      role: "Project Associate",
      description: "",
      icon: "user"
    },
    {
      name: "Mrs. Hasna Hameed",
      role: "Project Associate",
      description: "",
      icon: "user"
    },
    {
      name: "Ms. Arathy Surendran",
      role: "Project Associate",
      description: "",
      icon: "user"
    },
    {
      name: "Mr. Bhagyaraj J",
      role: "Project Assistant",
      description: "",
      icon: "user"
    },
    {
      name: "Mr. Amaljith N Raj",
      role: "Project Assistant",
      description: "",
      icon: "user"
    },
    {
      name: "Mrs. Jebina EA",
      role: "Project Assistant",
      description: "",
      icon: "user"
    }
  ];

  const projects = [
    {
      title: "Intelligent Sensor Module",
      description: "Developing a smart sensor module for real-time monitoring and management of environmental pollutants.",
      icon: "cpu"
    },
    {
      title: "Smart Water Level Monitoring",
      description: "A robust solution for monitoring water levels with an integrated alert system to mitigate flood risks.",
      icon: "droplet"
    },
    {
      title: "Digital Water Distribution",
      description: "Creating a digital twin to efficiently monitor and manage water distribution networks in urban areas.",
      icon: "layers"
    },
    {
      title: "Startup & Skill Development",
      description: "Fostering a vibrant startup ecosystem and providing skill development programs centered around our IoT solutions.",
      icon: "trending-up"
    },
    {
      title: "Explainable AI Software",
      description: "Building analysis software based on Explainable AI (XAI) to bring transparency and trust to complex IoT systems.",
      icon: "eye"
    }
  ];

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header Section */}
      <header className="sticky top-0 z-50 w-full bg-white/80 backdrop-blur-lg border-b border-slate-200/80">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <nav className="flex justify-between items-center h-16">
            {/* Logo */}
            <a href="#" target="_blank" className="flex items-center gap-3 group">
              <div className="w-10 h-10 rounded-lg bg-blue-500 flex items-center justify-center group-hover:bg-blue-600 transition-colors">
                <i data-feather="cpu" className="w-6 h-6 text-white"></i>
              </div>
              <span className="text-lg font-bold text-slate-800 hidden sm:inline">
                AI-IoT Innovations
              </span>
            </a>

            {/* Navigation Links */}
            <div className="hidden md:flex items-center gap-8">
              <a href="#about" className="text-sm font-medium text-slate-600 hover:text-blue-500 transition-colors">
                About
              </a>
              <a href="#team" className="text-sm font-medium text-slate-600 hover:text-blue-500 transition-colors">
                Team
              </a>
              <a href="#projects" className="text-sm font-medium text-slate-600 hover:text-blue-500 transition-colors">
                Projects
              </a>
              <a href="#contact" className="text-sm font-medium text-slate-600 hover:text-blue-500 transition-colors">
                Contact
              </a>
            </div>

            {/* CTA Button */}
            <div className="flex items-center gap-4">
              <a href="#contact" className="px-4 py-2 bg-blue-500 text-white text-sm font-medium rounded-lg hover:bg-blue-600 transition-colors">
                Get in Touch
              </a>
            </div>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1">
        {/* Hero Section */}
        <section className="hero-gradient py-20 reveal-on-scroll">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex flex-col lg:flex-row items-center gap-12">
              {/* Left Side - Text Content */}
              <div className="flex-1 text-center lg:text-left">
                <p className="inline-block px-4 py-2 bg-blue-50 text-blue-600 text-sm font-medium rounded-full mb-6">
                  Sponsored by Ministry of Electronics and Information Technology
                </p>
                <h1 className="text-4xl sm:text-5xl font-bold text-slate-800 mb-6 leading-tight">
                  Center for AI-IoT <span className="text-blue-500">Innovations</span>
                </h1>
                <p className="text-lg text-slate-600 mb-8">
                  The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design 
                  with artificial intelligence (AI) and explainable AI (XAI).
                </p>
                <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start">
                  <a href="#projects" className="px-6 py-3 bg-blue-500 text-white font-medium rounded-lg hover:bg-blue-600 transition-colors inline-flex items-center justify-center gap-2">
                    Explore Projects
                    <i data-feather="arrow-right" className="w-5 h-5"></i>
                  </a>
                  <a href="#team" className="px-6 py-3 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 transition-colors inline-flex items-center justify-center gap-2">
                    Meet the Team
                    <i data-feather="users" className="w-5 h-5"></i>
                  </a>
                </div>
              </div>

              {/* Right Side - Hero Image with Carousel */}
              <div className="flex-1">
                <div id="hero-image-container" className="relative">
                  {isLoading ? (
                    <div className="w-full h-96 bg-slate-200 rounded-2xl animate-pulse"></div>
                  ) : (
                    <img
                      id="hero-image"
                      src={heroImages[currentImageIndex]}
                      alt="AI IoT Innovation"
                      className="w-full h-96 object-cover rounded-2xl shadow-xl"
                    />
                  )}

                  {/* Carousel Indicators */}
                  {heroImages.length > 0 && (
                    <div id="carousel-indicators" className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex gap-2">
                      {heroImages.map((_, index) => (
                        <button
                          key={index}
                          onClick={() => handleIndicatorClick(index)}
                          className={`indicator w-3 h-3 rounded-full ${
                            index === currentImageIndex ? 'bg-blue-500 active' : 'bg-white/50'
                          }`}
                          aria-label={`Go to slide ${index + 1}`}
                        ></button>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* About Section */}
        <section id="about" className="py-20 reveal-on-scroll">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-16">
              <h2 className="text-3xl sm:text-4xl font-bold text-slate-800 mb-4">About Our Center</h2>
              <p className="text-lg text-slate-600">Pioneering research where intelligence meets connectivity.</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
              <div>
                <p className="text-slate-600 mb-6 leading-relaxed">
                  The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design 
                  with artificial intelligence (AI) and explainable AI (XAI). The lab is equipped with hardware development tools, 
                  computing systems, and educational resources to support research and development in this area.
                </p>
                <p className="text-slate-600 leading-relaxed">
                  The center provides resources for both theoretical research and practical applications, aiming to advance 
                  the integration of AI technologies with IoT systems.
                </p>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="p-6 bg-white border border-slate-200 rounded-xl hover:shadow-lg transition-shadow">
                  <i data-feather="zap" className="w-8 h-8 text-blue-500 mb-4"></i>
                  <h4 className="font-semibold text-slate-800 mb-2">Innovation</h4>
                  <p className="text-sm text-slate-600">State-of-the-art research facilities</p>
                </div>
                <div className="p-6 bg-white border border-slate-200 rounded-xl hover:shadow-lg transition-shadow">
                  <i data-feather="cpu" className="w-8 h-8 text-blue-500 mb-4"></i>
                  <h4 className="font-semibold text-slate-800 mb-2">Technology</h4>
                  <p className="text-sm text-slate-600">Advanced AI & IoT integration</p>
                </div>
                <div className="p-6 bg-white border border-slate-200 rounded-xl hover:shadow-lg transition-shadow">
                  <i data-feather="users" className="w-8 h-8 text-blue-500 mb-4"></i>
                  <h4 className="font-semibold text-slate-800 mb-2">Collaboration</h4>
                  <p className="text-sm text-slate-600">Expert faculty and researchers</p>
                </div>
                <div className="p-6 bg-white border border-slate-200 rounded-xl hover:shadow-lg transition-shadow">
                  <i data-feather="award" className="w-8 h-8 text-blue-500 mb-4"></i>
                  <h4 className="font-semibold text-slate-800 mb-2">Excellence</h4>
                  <p className="text-sm text-slate-600">Industry-leading solutions</p>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Team Section */}
        <section id="team" className="py-20 bg-slate-50 reveal-on-scroll">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-16">
              <h2 className="text-3xl sm:text-4xl font-bold text-slate-800 mb-4">Meet Our Expert Faculty</h2>
              <p className="text-lg text-slate-600">The brilliant minds leading our research and innovation.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {teamMembers.map((member, index) => (
                <div key={index} className="bg-white border border-slate-200 rounded-xl p-6 hover:shadow-lg transition-shadow">
                  <div className="flex items-start gap-4">
                    <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0">
                      <i data-feather={member.icon} className="w-6 h-6 text-blue-500"></i>
                    </div>
                    <div className="flex-1">
                      <h4 className="font-bold text-slate-800 mb-1">{member.name}</h4>
                      <p className="text-sm text-blue-500 font-medium mb-2">{member.role}</p>
                      {member.description && (
                        <p className="text-sm text-slate-600 leading-relaxed">{member.description}</p>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Projects Section */}
        <section id="projects" className="py-20 reveal-on-scroll">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-16">
              <h2 className="text-3xl sm:text-4xl font-bold text-slate-800 mb-4">Our Ongoing Projects</h2>
              <p className="text-lg text-slate-600">From concept to reality, we're building solutions that matter.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {projects.map((project, index) => (
                <div key={index} className="bg-white border border-slate-200 rounded-xl p-6 hover:shadow-lg transition-all hover:-translate-y-1">
                  <div className="w-12 h-12 rounded-lg bg-blue-50 flex items-center justify-center mb-4">
                    <i data-feather={project.icon} className="w-6 h-6 text-blue-500"></i>
                  </div>
                  <h4 className="font-bold text-slate-800 mb-3 text-lg">{project.title}</h4>
                  <p className="text-slate-600 text-sm leading-relaxed">{project.description}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Contact Section */}
        <section id="contact" className="py-20 bg-slate-50 reveal-on-scroll">
          <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
            <h2 className="text-3xl sm:text-4xl font-bold text-slate-800 mb-4">
              Let's Build the Future Together
            </h2>
            <p className="text-lg text-slate-600 mb-8">
              Have a project in mind, a question, or want to collaborate? We'd love to hear from you.
            </p>
            <a href="mailto:contact@aiiot.edu" className="inline-flex items-center gap-2 px-6 py-3 bg-blue-500 text-white font-medium rounded-lg hover:bg-blue-600 transition-colors">
              <i data-feather="mail" className="w-5 h-5"></i>
              Contact Us
            </a>
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="bg-slate-800 text-slate-300 py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div>
              <h5 className="font-bold text-white mb-4">AI-IoT Innovations</h5>
              <p className="text-sm">
                Advancing the integration of AI and IoT technologies for a smarter tomorrow.
              </p>
            </div>
            <div>
              <h5 className="font-bold text-white mb-4">Quick Links</h5>
              <ul className="space-y-2">
                <li><a href="#about" className="text-sm hover:text-blue-400 transition-colors">About</a></li>
                <li><a href="#team" className="text-sm hover:text-blue-400 transition-colors">Team</a></li>
                <li><a href="#projects" className="text-sm hover:text-blue-400 transition-colors">Projects</a></li>
                <li><a href="#contact" className="text-sm hover:text-blue-400 transition-colors">Contact</a></li>
              </ul>
            </div>
            <div>
              <h5 className="font-bold text-white mb-4">Connect</h5>
              <div className="flex gap-4">
                <a href="#" className="w-10 h-10 bg-slate-700 rounded-lg flex items-center justify-center hover:bg-blue-500 transition-colors">
                  <i data-feather="linkedin" className="w-5 h-5"></i>
                </a>
                <a href="#" className="w-10 h-10 bg-slate-700 rounded-lg flex items-center justify-center hover:bg-blue-500 transition-colors">
                  <i data-feather="twitter" className="w-5 h-5"></i>
                </a>
                <a href="#" className="w-10 h-10 bg-slate-700 rounded-lg flex items-center justify-center hover:bg-blue-500 transition-colors">
                  <i data-feather="mail" className="w-5 h-5"></i>
                </a>
              </div>
            </div>
          </div>
          <div className="border-t border-slate-700 mt-8 pt-8 text-center text-sm">
            <p>&copy; 2025 Center for AI-IoT Innovations. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default Aiiot_innovation;
